      "BARUDAN. Upper Thread Path Dynamics and Pre-Tension Tuning. Tokyo, 2023.",
      "ARTRELADOS. Passagem de Linha Perfeita: O Caminho do Cone até a Agulha. São Paulo: Artrelados, 2024."
